#!/usr/bin/env node
/**
 * apply-patch.mjs — CHẠY 1 LẦN: cài khung Agent phân tích dữ liệu vào dự án của bạn.
 *
 *   node apply-patch.mjs                      (cài vào thư mục hiện tại)
 *   node apply-patch.mjs D:\duong\dan\du-an   (chỉ định dự án)
 *   --dir=src/framework   nơi đặt file (mặc định: src/framework nếu có src/, ngược lại framework/)
 *   --dry-run             chỉ in kế hoạch, không ghi gì
 *   --no-install          không tự cài pptxgenjs
 *   --no-test             bỏ qua bước tự kiểm tra
 *   --no-scan             bỏ qua bước quét mã nguồn
 *   --undo                hoàn tác (khôi phục file cũ / xoá file đã thêm)
 *
 * Patch này CHỈ THÊM file mới (và sao lưu nếu trùng tên). Nó KHÔNG sửa mã hiện có của bạn.
 * Phần quét sẽ chỉ ra chính xác dòng nào cần nối vào (MLAB, báo lỗi bước, Base URL) trong PATCH_REPORT.md.
 */
import fs from 'node:fs';
import path from 'node:path';
import crypto from 'node:crypto';
import os from 'node:os';
import { spawnSync } from 'node:child_process';
import { pathToFileURL } from 'node:url';

const PAYLOAD = {
 "providers.js": {
  "sha256": "565d4197edf87cb7f39ef65204081cc4136eb7fbbe984b26eb2dcc2eca4145f6",
  "b64": ""
 },
 "chart-advisor.js": {
  "sha256": "7ea8e1a9e770b6fdf170d879ca60d27e962818de95ea645fa63d9832d9ff4db0",
  "b64": ""
 },
 "pipeline-core.js": {
  "sha256": "38f0218d451dc8128acfdb832ecb63933c88ce9ab1daffc9c691fa1638b84cdf",
  "b64": ""
 },
 "deck-builder.js": {
  "sha256": "27fda0a9fea199bd45eb12811fa78b0fb4669d7a34b40b89fcfe7f4769f20bbd",
  "b64": ""
 },
 "agent-playbooks.md": {
  "sha256": "3e14e4c6b34be2a34fe1e241bc8015cd7e0390c7c9c0bd1b8cf8d6701223e89e",
  "b64": ""
 }
};

const argv = process.argv.slice(2);
const has = (n) => argv.includes(`--${n}`);
const val = (n) => { const a = argv.find((x) => x.startsWith(`--${n}=`)); return a ? a.slice(n.length + 3) : null; };
const log = (...a) => console.log(...a);
const die = (m) => { console.error(`\n✗ ${m}`); process.exit(1); };

if (has('help')) { log(fs.readFileSync(new URL(import.meta.url), 'utf8').split('*/')[0]); process.exit(0); }
if (Number(process.versions.node.split('.')[0]) < 18) die(`Cần Node.js 18 trở lên (hiện tại ${process.versions.node}).`);

const root = path.resolve(argv.find((a) => !a.startsWith('--')) || process.cwd());
if (!fs.existsSync(root) || !fs.statSync(root).isDirectory()) die(`Không thấy thư mục dự án: ${root}`);
const dest = path.resolve(root, val('dir') || (fs.existsSync(path.join(root, 'src')) ? 'src/framework' : 'framework'));
const dry = has('dry-run');
const MANIFEST = path.join(dest, '.patch-manifest.json');
const rel = (p) => path.relative(root, p) || '.';
const readManifest = () => (fs.existsSync(MANIFEST) ? JSON.parse(fs.readFileSync(MANIFEST, 'utf8')) : null);

/* ------------------------------ UNDO ------------------------------ */
if (has('undo')) {
  const m = readManifest();
  if (!m) die('Không thấy manifest — patch chưa từng được áp ở thư mục này.');
  for (const f of m.files) {
    const p = path.join(dest, f.name);
    if (f.backup && fs.existsSync(path.join(dest, f.backup))) { fs.copyFileSync(path.join(dest, f.backup), p); fs.unlinkSync(path.join(dest, f.backup)); log(`↩ khôi phục ${f.name}`); }
    else if (f.created && fs.existsSync(p)) { fs.unlinkSync(p); log(`🗑  xoá ${f.name}`); }
  }
  fs.unlinkSync(MANIFEST);
  try { fs.unlinkSync(path.join(dest, 'PATCH_REPORT.md')); } catch { /* không có */ }
  try { fs.rmdirSync(dest); } catch { /* còn file khác thì giữ */ }
  log('Đã hoàn tác. (pptxgenjs, nếu đã cài, được giữ nguyên.)');
  process.exit(0);
}

/* --------------------------- 1. Kiểm payload --------------------------- */
const files = Object.entries(PAYLOAD).map(([name, p]) => {
  const buf = Buffer.from(p.b64, 'base64');
  if (crypto.createHash('sha256').update(buf).digest('hex') !== p.sha256) die(`File patch bị hỏng (sai checksum): ${name}. Tải lại apply-patch.mjs.`);
  return { name, buf };
});
log(`\n▶ Dự án : ${root}\n▶ Đích   : ${rel(dest)}\n▶ Chế độ: ${dry ? 'DRY-RUN (không ghi gì)' : 'áp dụng'}\n`);

/* --------------------------- 2. Ghi file --------------------------- */
const prev = readManifest();
const entries = new Map((prev?.files || []).map((f) => [f.name, f]));
const stamp = new Date().toISOString().replace(/[:.]/g, '-');
const results = [];
if (!dry) fs.mkdirSync(dest, { recursive: true });

for (const { name, buf } of files) {
  const target = path.join(dest, name);
  const old = entries.get(name);
  if (!fs.existsSync(target)) {
    if (!dry) fs.writeFileSync(target, buf);
    entries.set(name, { name, created: true, backup: old?.backup || null });
    results.push(['+', name, 'thêm mới']);
  } else if (fs.readFileSync(target).equals(buf)) {
    if (!entries.has(name)) entries.set(name, { name, created: false, backup: null });
    results.push(['=', name, 'đã có, giống hệt']);
  } else {
    const bak = `${name}.bak-${stamp}`;
    if (!dry) { fs.copyFileSync(target, path.join(dest, bak)); fs.writeFileSync(target, buf); }
    entries.set(name, { name, created: old?.created ?? false, backup: old ? (old.created ? null : old.backup || bak) : bak }); // file do patch tạo ra thì undo = xoá; bản sửa tay vẫn còn trong file .bak
    results.push(['~', name, `ghi đè (bản cũ lưu ở ${bak})`]);
  }
}

// Các file là ES module: nếu dự án chưa khai báo "type":"module", đặt package.json cục bộ cho riêng thư mục này.
let rootPkg = null;
try { rootPkg = JSON.parse(fs.readFileSync(path.join(root, 'package.json'), 'utf8')); } catch { /* không có */ }
const localPkg = path.join(dest, 'package.json');
if (rootPkg?.type !== 'module' && !fs.existsSync(localPkg)) {
  if (!dry) fs.writeFileSync(localPkg, '{ "type": "module" }\n');
  entries.set('package.json', { name: 'package.json', created: true, backup: null });
  results.push(['+', 'package.json', 'khai báo "type":"module" cho thư mục này']);
}
for (const [s, n, note] of results) log(`  ${s} ${n.padEnd(20)} ${note}`);
if (!dry) fs.writeFileSync(MANIFEST, JSON.stringify({ appliedAt: new Date().toISOString(), files: [...entries.values()] }, null, 2));

/* --------------------------- 3. Cài pptxgenjs --------------------------- */
let pptxNote = '';
const hasPptx = () => fs.existsSync(path.join(root, 'node_modules', 'pptxgenjs'));
if (rootPkg && !has('no-install') && !hasPptx()) {
  if (dry) pptxNote = 'sẽ chạy: npm install pptxgenjs';
  else {
    log('\n▶ Cài pptxgenjs (cho bộ xuất PowerPoint)…');
    const r = spawnSync('npm', ['install', 'pptxgenjs'], { cwd: root, stdio: 'inherit', shell: process.platform === 'win32' });
    pptxNote = r.status === 0 ? 'đã cài pptxgenjs' : 'KHÔNG cài được pptxgenjs — chạy tay: npm install pptxgenjs';
  }
} else if (!rootPkg) pptxNote = 'không thấy package.json — bỏ qua; khi dùng deck-builder.js hãy cài: npm install pptxgenjs';
else pptxNote = hasPptx() ? 'pptxgenjs đã có sẵn' : 'bỏ qua cài đặt (--no-install)';
if (pptxNote) log(`  • ${pptxNote}`);

/* --------------------------- 4. Tự kiểm tra --------------------------- */
async function smoke() {
  const out = [];
  const t = (name, cond) => out.push({ name, ok: !!cond });
  const imp = (n) => import(pathToFileURL(path.join(dest, n)).href);
  try {
    const P = await imp('providers.js'), A = await imp('chart-advisor.js'), C = await imp('pipeline-core.js');
    let cfg = P.createConfig('openai'); cfg.keys = { openai: 'k' }; cfg.model = 'gemini-2.5-flash';
    const v = P.validateConfig(cfg);
    t('Model Gemini dưới provider OpenAI bị bắt + có nút sửa', !v.ok && v.fixes[0]?.type === 'switchProvider');
    t('Sửa tự động → Base URL Gemini', P.resolveBaseUrl(P.applyFix(cfg, v.fixes[0])).includes('generativelanguage.googleapis.com'));
    t('Đổi provider thì Base URL tuỳ chỉnh được reset', P.changeProvider({ ...cfg, baseUrlOverride: 'https://x.y' }, 'gemini').baseUrlOverride === null);

    const dot = (n) => String(n).replace(/\B(?=(\d{3})+(?!\d))/g, '.');
    const rows = Array.from({ length: 40 }, (_, i) => ({ 'Ngày': `${String((i % 28) + 1).padStart(2, '0')}/09/2026`, 'Loại': i % 4 === 3 ? 'Hoàn' : 'Bán', 'Chi tiết': i < 8 ? 'X' + i : '', 'Giá trị': (i % 4 === 3 ? '-' : '') + dot(100000 + i * 1237) }));
    const prof = A.profileDataset(rows);
    t('Đọc đúng số kiểu 1.234.567 và nhận là chỉ số đo', prof.columns['Giá trị'].type === 'number' && prof.columns['Giá trị'].role === 'measure');
    t('Phát hiện cột phân loại bản ghi cần quyết định phạm vi', C.scopeCandidates(prof).some((s) => s.column === 'Loại'));
    const comp = A.recommendCharts({ profile: prof, intent: 'composition', measure: 'Giá trị', dimension: 'Chi tiết' });
    t('Chặn biểu đồ cơ cấu trên cột thiếu 80%', !comp.primary && comp.blocked.length > 0);

    const f = new C.FactsStore(); f.add({ id: 'a', label: 'a', value: 19171000, unit: 'currency' });
    t('FactsStore bắt số bịa, chấp nhận số đúng', f.verify('khoảng 19,2 tr').ok && !f.verify('tổng 25 tr').ok);
    t('extractJson chịu code fence + dấu phẩy thừa', C.extractJson('```json\n{"a":[1,2,]}\n```').a.length === 2);
    const st = await C.runStage({ id: 'x', run: async () => { return __KHONG_TON_TAI__.x; } });
    t('Lỗi "is not defined" được chẩn đoán kèm gợi ý', st.status === 'error' && !!st.error.hint);
    const sr = C.safeRender('x', () => 1, { requires: ['__KHONG_TON_TAI__'], onError: () => {} });
    t('safeRender báo sớm biến thiếu và có phương án thay thế', !sr.ok && sr.fallback.includes('retry'));
  } catch (e) { t(`Nạp module thất bại: ${e.message}`, false); }
  try {
    const D = await imp('deck-builder.js');
    const { result, warnings } = await D.buildDeck({ meta: { title: 'Thử nghiệm' }, slides: [{ type: 'summary', title: 'Kết luận có số liệu', answer: 'Trả lời.', points: [{ head: 'Ý', text: 'Nội dung.' }], notes: 'n' }] }, {});
    t('Dựng được file .pptx hợp lệ (zip) và lint sạch', result && result[0] === 0x50 && result[1] === 0x4b && warnings.length === 0);
  } catch (e) { out.push({ name: `Bộ xuất PowerPoint: bỏ qua (${/pptxgenjs/.test(e.message) ? 'chưa cài pptxgenjs' : e.message})`, ok: null }); }
  return out;
}
let smokeOut = [];
if (!dry && !has('no-test')) {
  log('\n▶ Tự kiểm tra…');
  smokeOut = await smoke();
  for (const r of smokeOut) log(`  ${r.ok === null ? '–' : r.ok ? '✓' : '✗'} ${r.name}`);
}

/* --------------------------- 5. Quét mã nguồn --------------------------- */
const SKIP = new Set(['node_modules', '.git', 'dist', 'build', '.next', '.nuxt', 'coverage', 'out', '.cache', '.turbo', '.vite', '.svelte-kit']);
const EXT = new Set(['.js', '.jsx', '.ts', '.tsx', '.mjs', '.cjs', '.html', '.htm', '.vue', '.svelte']);
function* walk(dir) {
  for (const e of fs.readdirSync(dir, { withFileTypes: true })) {
    if (SKIP.has(e.name)) continue;
    const p = path.join(dir, e.name);
    if (p.startsWith(dest)) continue;
    if (e.isDirectory()) yield* walk(p);
    else if (EXT.has(path.extname(e.name).toLowerCase())) { try { if (fs.statSync(p).size < 1.5e6) yield p; } catch { /* bỏ qua */ } }
  }
}
const DEF_RE = [/(?:window|globalThis|self)\s*\.\s*MLAB\s*=/, /\b(?:const|let|var)\s+MLAB\b/, /\bfunction\s+MLAB\b/, /\bclass\s+MLAB\b/, /\bexport\s+(?:const|let|var|function|class)\s+MLAB\b/, /\bexport\s*\{[^}]*\bMLAB\b/];
const IMPORT_RE = /\bimport\b[\s\S]{0,400}?\bMLAB\b[\s\S]{0,200}?\bfrom\b/;
const GLOBAL_RE = /(?:window|globalThis|self)\s*\.\s*MLAB\s*=|\bvar\s+MLAB\b/;
const declares = (src) => DEF_RE.some((r) => r.test(src)) || IMPORT_RE.test(src);

const scan = { mlab: [], stepErr: [], stepName: [], baseUrl: [], defFiles: [], useOnlyFiles: [], scanned: 0 };
if (!has('no-scan')) {
  log('\n▶ Quét mã nguồn…');
  const lineHits = (src, re, cap, file, bucket) => {
    const lines = src.split(/\r?\n/);
    for (let i = 0; i < lines.length && bucket.length < cap; i++) if (re.test(lines[i])) bucket.push({ file: rel(file), line: i + 1, text: lines[i].trim().slice(0, 150) });
  };
  for (const file of walk(root)) {
    scan.scanned++;
    const src = fs.readFileSync(file, 'utf8');
    if (/\bMLAB\b/.test(src)) {
      const own = declares(src);
      lineHits(src, /\bMLAB\b/, 200, file, scan.mlab);
      (own ? scan.defFiles : scan.useOnlyFiles).push({ file: rel(file), global: GLOBAL_RE.test(src) });
    }
    lineHits(src, /Không hiển thị được bước này|Khong hien thi duoc buoc nay/, 10, file, scan.stepErr);
    lineHits(src, /api\.openai\.com|generativelanguage\.googleapis\.com|api\.anthropic\.com|\bbase[_\s-]?url\b/i, 40, file, scan.baseUrl);
  }
  log(`  • đã quét ${scan.scanned} file; MLAB: ${scan.mlab.length} dòng; hiển thị lỗi bước: ${scan.stepErr.length}; Base URL: ${scan.baseUrl.length}`);
}

/* --------------------------- 6. Báo cáo --------------------------- */
function mlabVerdict() {
  if (has('no-scan')) return 'Đã bỏ qua quét.';
  if (!scan.mlab.length) return 'Không thấy `MLAB` trong mã nguồn web của dự án (có thể nằm ở thư viện bên ngoài, file đã build, hoặc backend). Bước này lỗi vì biến được tham chiếu lúc chạy mà chưa tồn tại — hãy tìm trong file build/bundle đang chạy.';
  const parts = [];
  if (!scan.defFiles.length) parts.push('**Không có nơi nào định nghĩa/import `MLAB`** trong dự án → `ReferenceError` là chắc chắn. Thường do file/thư viện chứa `MLAB` chưa được thêm, hoặc đã bị đổi tên/xoá khi refactor. Hãy khôi phục định nghĩa hoặc thay các chỗ dùng bên dưới.');
  else {
    parts.push(`Có định nghĩa/import \`MLAB\` ở: ${scan.defFiles.map((d) => `\`${d.file}\`${d.global ? ' (gán toàn cục)' : ''}`).join(', ')}.`);
    if (scan.useOnlyFiles.length) parts.push(`Các file **dùng \`MLAB\` nhưng không tự import/định nghĩa**: ${scan.useOnlyFiles.map((d) => `\`${d.file}\``).join(', ')}. ${scan.defFiles.some((d) => d.global) ? 'Vì `MLAB` được gán toàn cục, hãy kiểm tra thứ tự nạp script (file gán phải nạp TRƯỚC) và xem bước này có chạy trong iframe/Function/Worker (không thừa hưởng biến toàn cục) không.' : 'Hãy thêm `import` tương ứng ở các file này.'}`);
    else parts.push('Mọi file dùng `MLAB` đều có khai báo/import — lỗi nhiều khả năng do thứ tự nạp hoặc phạm vi chạy (iframe/Worker/`new Function`).');
  }
  return parts.join('\n\n');
}
const table = (rows, empty) => (rows.length ? rows.map((r) => `- \`${r.file}:${r.line}\` — \`${r.text.replace(/`/g, "'")}\``).join('\n') : `_${empty}_`);
const R = path.relative(root, dest).split(path.sep).join('/');
const report = `# PATCH REPORT

Áp lúc ${new Date().toLocaleString('vi-VN')} · dự án \`${root}\` · đích \`${R}/\`

## Đã cài
${results.map(([s, n, note]) => `- \`${s}\` ${n} — ${note}`).join('\n')}
- pptxgenjs: ${pptxNote || '—'}

## Tự kiểm tra
${smokeOut.length ? smokeOut.map((r) => `- ${r.ok === null ? '–' : r.ok ? '✓' : '✗'} ${r.name}`).join('\n') : '_(không chạy)_'}

## 1. Lỗi \`MLAB is not defined\`
${mlabVerdict()}

Các dòng có \`MLAB\`:
${table(scan.mlab.slice(0, 40), 'không có')}

## 2. Nơi hiển thị "Không hiển thị được bước này"
Bọc hàm render của từng bước bằng \`safeRender\` ở đây để lỗi hiện kèm chẩn đoán + nút thử lại, và để dấu ✓ lấy từ kết quả chạy thật:
${table(scan.stepErr, 'không tìm thấy chuỗi này (có thể thông báo được ghép từ nhiều phần)')}

## 3. Base URL đang viết cứng / lưu độc lập
Thay bằng \`resolveBaseUrl(cfg)\`; ô Provider gọi \`changeProvider\`:
${table(scan.baseUrl, 'không tìm thấy')}

## 4. Nối vào (copy–paste)
\`\`\`js
// Tab API & Model
import { PROVIDERS, createConfig, changeProvider, resolveBaseUrl, validateConfig, applyFix, listModels, testConnection, callLLM } from './${R.replace(/^src\//, '')}/providers.js';
//  - đổi Provider  : cfg = changeProvider(cfg, providerId)          // Base URL tự về mặc định
//  - hiển thị URL  : resolveBaseUrl(cfg)                             // readonly; nút "Tuỳ chỉnh" mới ghi cfg.baseUrlOverride
//  - trước khi chạy: const v = validateConfig(cfg); nếu !v.ok -> hiện v.errors và nút cho từng v.fixes (cfg = applyFix(cfg, fix))
//  - nút Kiểm tra  : await testConnection(cfg)

// Mỗi bước của pipeline
import { runStage, safeRender, FactsStore } from './${R.replace(/^src\//, '')}/pipeline-core.js';
const r = safeRender('clean', () => renderCleanStep(state));        // thay cho render trực tiếp
if (!r.ok) showStepError(r.diagnostics);                             // .message, .hint, .stack; r.fallback = ['show-raw-output','retry','copy-diagnostics']
\`\`\`
Chi tiết prompt và quy tắc cho các Agent: \`${R}/agent-playbooks.md\`.

Hoàn tác: \`node apply-patch.mjs --undo\`
`;
if (!dry) fs.writeFileSync(path.join(dest, 'PATCH_REPORT.md'), report);

/* --------------------------- 7. Tổng kết --------------------------- */
const failed = smokeOut.filter((r) => r.ok === false).length;
log(`\n${failed ? '✗' : '✓'} Xong. ${dry ? '(dry-run — chưa ghi gì)' : `Báo cáo chi tiết: ${rel(path.join(dest, 'PATCH_REPORT.md'))}`}`);
if (!dry && !has('no-scan')) {
  log(`   MLAB: ${!scan.mlab.length ? 'không thấy trong mã nguồn' : !scan.defFiles.length ? 'KHÔNG có định nghĩa nào → đây là nguyên nhân lỗi' : `định nghĩa ở ${scan.defFiles.map((d) => d.file).join(', ')}`}`);
}
log('   Hoàn tác: node apply-patch.mjs --undo');
process.exit(failed ? 1 : 0);
